    # Bağımlılık yönünde graf: paket -> bağımlılıkları
    dep_adj = {node: [] for node in remaining}
    for pkg in remaining:
        for dep in deps.get(pkg, []):
            if dep in remaining:
                dep_adj[pkg].append(dep)
    for node in dep_adj:
        dep_adj[node].sort()

    visited = set()
    rec_stack = []  # DFS yolu
    on_stack = set()

    def dfs(node: str) -> list[str] | None:
